import{_ as i,o as a,c as t,a3 as s}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"从源码构建","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"从源码构建 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/dev/build"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/dev/build"}]]},"headers":[],"relativePath":"zh/catter/dev/build.md","filePath":"zh/catter/dev/build.md","lastUpdated":1793109318000}'),l={name:"zh/catter/dev/build.md"};function d(o,e,n,r,c,h){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h1><h2 id="前置要求" tabindex="-1">前置要求 <a class="header-anchor" href="#前置要求" aria-label="Permalink to &quot;前置要求&quot;">​</a></h2><ul><li><a href="https://pixi.sh" target="_blank" rel="noreferrer">pixi</a> -- 环境与依赖管理；其余的一切，包括 Bazel，都由它带来</li><li>Git</li></ul><h2 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>目标</th><th>在哪里构建</th></tr></thead><tbody><tr><td>Linux x64</td><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux</td></tr><tr><td>macOS arm64</td><td><code>aarch64-apple-darwin</code></td><td>macOS</td></tr><tr><td>Windows x64</td><td><code>x86_64-w64-mingw32</code></td><td>Linux、Windows</td></tr><tr><td>Windows on ARM</td><td><code>aarch64-w64-mingw32</code></td><td>Linux、Windows</td></tr></tbody></table><p>每个平台都用 <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a> 23.1.3 的工具链构建，由 Bazel 下载：clang、lld 和 libc++，libc++ 链接进每个程序，所以程序只依赖系统自带的库。Linux 上的程序在 glibc 2.17 及以上运行，macOS 上的程序在 macOS 15 及以上运行。Windows 上的程序是 MinGW 的，每次 Windows 构建都会同时生成 x64 和 ARM64 两种架构的钩子 DLL。</p><h2 id="构建命令" tabindex="-1">构建命令 <a class="header-anchor" href="#构建命令" aria-label="Permalink to &quot;构建命令&quot;">​</a></h2><p>所有构建通过 pixi 任务管理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the programs, the hook libraries and the unit tests (RelWithDebInfo)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The ASan build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build for Windows on ARM from Linux or Windows x64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RelWithDebInfo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platforms=@xclang//platforms:aarch64-w64-mingw32</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The release package, build/RelWithDebInfo/bin/catter.tar.gz (catter.zip on Windows)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RelWithDebInfo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:package</span></span></code></pre></div><p>程序生成在 <code>build/&lt;type&gt;/bin/bin</code>，彼此相邻，catter 就在这里找到它们。构建类型有两种：<code>RelWithDebInfo</code>，开启优化并带调试信息，即发布的版本；<code>Debug</code>，开启 AddressSanitizer，Windows on ARM 没有这种构建。</p><p>在 Windows 上，Bazel 默认的输出根目录对 Windows 路径来说太深，在 <code>%USERPROFILE%\\.bazelrc</code> 中设置一个较短的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startup --output_user_root=C:/b</span></span></code></pre></div><h2 id="构建系统" tabindex="-1">构建系统 <a class="header-anchor" href="#构建系统" aria-label="Permalink to &quot;构建系统&quot;">​</a></h2><p>项目使用 <a href="https://bazel.build" target="_blank" rel="noreferrer">Bazel</a>，通过 npm 上的 bazelisk 运行（<code>pnpm exec bazel</code>），版本由 <code>.bazelversion</code> 指定；依赖来自 clice 的 Bazel registry <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a>。C++ 标准为 C++23。<code>pixi run -e dev pnpm exec bazel run @compdb//:refresh</code> 为编辑器生成 <code>compile_commands.json</code>。</p><p><code>src/support</code> 之上的 catter 代码是 C++20 具名模块：<code>src/command</code> 是 <code>catter.command</code>，其余是 <code>catter</code>。钩子库和它们共用的 <code>src/support</code> 仍是头文件。第三方库合为一个模块 <code>deps</code>，<code>modules/</code> 里存有 CI 构建的每种配置下的它；<code>scripts/modules.py</code> 用 <code>clice modularize</code> 从 <code>modules/demand.cpp</code> 生成它。</p><h3 id="构建目标" tabindex="-1">构建目标 <a class="header-anchor" href="#构建目标" aria-label="Permalink to &quot;构建目标&quot;">​</a></h3><ul><li><code>bin/catter</code> -- 主 CLI 可执行文件（DECISION 守护进程）</li><li><code>bin/catter-proxy</code> -- 代理进程管理器，也是 wrapper 后端的 shim（包装程序）</li><li><code>hook_unix_payload</code> -- Unix 钩子共享库（Linux/macOS），即 <code>bin/libcatter-hook-unix.so</code> 或 <code>.dylib</code></li><li><code>hook_x64_payload</code>、<code>hook_arm64_payload</code> -- Windows 钩子 DLL，即 <code>bin/catter-hook-x64.dll</code> 和 <code>bin/catter-hook-arm64.dll</code>，每种架构一个，每次 Windows 构建都会同时生成两者</li><li><code>support</code>、<code>command</code>、<code>session</code>、<code>capture</code>（以及 <code>capture_inject</code>）、<code>protocol</code>、<code>feature</code> -- 库，<code>src/</code> 下每个目录一个</li><li><code>dist</code> -- <code>pixi run -e dev build</code> 构建的内容；<code>package</code> 和 <code>symbols</code> -- 发布包及其调试符号</li></ul><h2 id="主要依赖" tabindex="-1">主要依赖 <a class="header-anchor" href="#主要依赖" aria-label="Permalink to &quot;主要依赖&quot;">​</a></h2><ul><li><a href="https://github.com/gabime/spdlog" target="_blank" rel="noreferrer">spdlog</a> (1.15.3) -- 日志</li><li><a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a> -- 异步运行时、测试框架、选项解析</li><li><a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a> -- Windows API 钩子与 DLL 注入（仅 Windows）</li></ul>`,19)])])}const u=i(l,[["render",d]]);export{k as __pageData,u as default};
